      sources: [{ name: "Taylor Swift Says '1989 (Taylor's Version)' Is Coming at L.A. Finale", url: "https://variety.com/2023/music/news/taylor-swift-announces-1989-taylors-version-coming-la-tour-finale-sofi-stadium-1235692622/" }, { name: "Taylor Swift announces '1989 (Taylor's Version)' at final U.S. Eras Tour show this year", url: "https://www.washingtonpost.com/arts-entertainment/2023/08/10/taylor-swift-1989-taylors-version/" }],
