      sources: [{ name: "Taylor Swift Changes Lyric, Kisses Travis Kelce in Buenos Aires", url: "https://www.billboard.com/music/music-news/taylor-swift-travis-kelce-kiss-karma-is-the-guy-on-the-chiefs-1235469366/" }, { name: "Travis Kelce reacts to Taylor Swift's changing 'Karma' lyrics to refer to the Chiefs", url: "https://www.nbcnews.com/pop-culture/celebrity/travis-kelce-reacts-taylor-swift-karma-lyric-change-rcna124807" }],
