      sources: [{ name: "Taylor Swift concerts in Vienna canceled after Austrian police say foiled terrorist plot targeted shows", url: "https://www.nbcnews.com/news/world/taylor-swift-concert-terror-plot-austria-foiled-2-men-arrested-shows-w-rcna165591" }, { name: "Taylor Swift's Eras Tour resumes in London after foiled Vienna terror plot", url: "https://www.cbsnews.com/news/taylor-swift-eras-tour-resumes-london-foiled-vienna-terror-plot/" }],
